function orderlyQueue(s, k) {
  // Explore every reachable string with a breadth-first search.
  const seen = new Set([s]);
  const queue = [s];
  let best = s;
  while (queue.length) {
    const cur = queue.shift();
    if (cur < best) best = cur;
    for (let i = 0; i < k; i++) {
      const next = cur.slice(0, i) + cur.slice(i + 1) + cur[i];
      if (!seen.has(next)) { seen.add(next); queue.push(next); }
    }
  }
  return best;
}

