function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 6);
  const letters = size === 'large' ? 26 : 1 + Math.floor(rand() * 4);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  const k = rand() < 0.45 ? 1 : 1 + Math.floor(rand() * n);
  return [s, k];
}
